def merge(x, y):
    i = j = 0
    out = []
    while i < len(x) and j < len(y):
        if x[i] <= y[j]:
            out.append(x[i]); i += 1
        else:
            out.append(y[j]); j += 1
    out.extend(x[i:])
    out.extend(y[j:])
    return out

def merge_sort_iter(a):
    width = 1
    n = len(a)
    while width < n:
        for left in range(0, n, 2 * width):
            mid = min(left + width, n)
            right = min(left + 2 * width, n)
            a[left:right] = merge(a[left:mid], a[mid:right])
        width *= 2
    return a

def partition(a, lo, hi):
    pivot = a[hi]
    i = lo
    for j in range(lo, hi):
        if a[j] < pivot:
            a[i], a[j] = a[j], a[i]
            i += 1
    a[i], a[hi] = a[hi], a[i]
    return i

def quick_sort(a, lo, hi):
    if lo < hi:
        p = partition(a, lo, hi)
        quick_sort(a, lo, p - 1)
        quick_sort(a, p + 1, hi)
    return a

def partition_hoare(a, lo, hi):
    pivot = a[(lo + hi) // 2]
    i, j = lo, hi
    while True:
        while a[i] < pivot:
            i += 1
        while a[j] > pivot:
            j -= 1
        if i >= j:
            return j
        a[i], a[j] = a[j], a[i]
        i += 1
        j -= 1

def partition3(a, lo, hi):
    lt, i, gt = lo, lo, hi
    v = a[lo]
    while i <= gt:
        if a[i] < v:
            a[lt], a[i] = a[i], a[lt]
            lt += 1; i += 1
        elif a[i] > v:
            a[i], a[gt] = a[gt], a[i]
            gt -= 1
        else:
            i += 1
    return lt, gt

def sift_down(a, n, i):
    while True:
        l = 2 * i + 1
        r = 2 * i + 2
        m = i
        if l < n and a[l] > a[m]:
            m = l
        if r < n and a[r] > a[m]:
            m = r
        if m == i:
            break
        a[i], a[m] = a[m], a[i]
        i = m

def build_heap(a):
