def counting_sort(a, k):
    count = [0] * (k + 1)
    for v in a:
        count[v] += 1
    for i in range(1, k + 1):
        count[i] += count[i - 1]
    out = [0] * len(a)
    for v in reversed(a):
        count[v] -= 1
        out[count[v]] = v
    return out

def counting_compact(a, k):
    count = [0] * (k + 1)
    for v in a:
        count[v] += 1
    out = []
    for i, c in enumerate(count):
        out.extend([i] * c)
    return out

def radix_sort(a):
    if not a:
        return a
    m = max(a)
    exp = 1
    while m // exp > 0:
        count = [0] * 10
        for v in a:
            count[(v // exp) % 10] += 1
        for i in range(1, 10):
            count[i] += count[i - 1]
        out = [0] * len(a)
        for v in reversed(a):
            d = (v // exp) % 10
            count[d] -= 1
            out[count[d]] = v
        a = out
        exp *= 10
    return a

