def top_k_frequent(nums, k):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    buckets = [[] for _ in range(len(nums) + 1)]
    for v, c in cnt.items():
        buckets[c].append(v)
    res = []
    for b in range(len(buckets) - 1, 0, -1):
        res.extend(buckets[b])
        if len(res) >= k:
            break
    return res[:k]

